export enum ProductCategory {
  Breakfast = 'breakfast',
  Lunch = 'lunch',
  Snacks = 'snacks',
  Beverages = 'beverages'
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: ProductCategory;
  imageUrl: string;
  isAvailable: boolean;
  preparationTime: number; // minutes
  calories?: number;
}

