import { Timestamp } from 'firebase/firestore';
import { CURRENCY_SYMBOL } from '../constants';

export const formatPrice = (price: number): string => {
  return `${CURRENCY_SYMBOL}${price.toFixed(2)}`;
};

export const formatTime = (timestamp: Timestamp | Date): string => {
  const date = timestamp instanceof Timestamp ? timestamp.toDate() : timestamp;
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
};

export const formatDate = (timestamp: Timestamp | Date): string => {
  const date = timestamp instanceof Timestamp ? timestamp.toDate() : timestamp;
  return date.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
};

export const generateTimeSlots = (): Date[] => {
  const slots: Date[] = [];
  const now = new Date();
  const start = new Date(now);
  start.setMinutes(Math.ceil(start.getMinutes() / 15) * 15, 0, 0); // Round up to next 15 min

  // Generate for next 24 hours
  for (let i = 0; i < 24 * 4; i++) {
    const slotTime = new Date(start.getTime() + i * 15 * 60000);
    const hour = slotTime.getHours();
    // Only business hours
    if (hour >= 8 && hour < 20) {
      slots.push(slotTime);
    }
  }
  return slots;
};

import { 
  collection, 
  doc, 
  getDocs, 
  addDoc, 
  updateDoc, 
  runTransaction, 
  query, 
  where, 
  orderBy, 
  Timestamp,
  serverTimestamp,
  onSnapshot,
  setDoc,
  increment
} from 'firebase/firestore';
import { db } from '../firebase';
import { MenuItem, Order, OrderStatus, TimeSlot, UserRole, ProductCategory } from '../types';
import { MAX_ORDERS_PER_SLOT } from '../constants';

// --- MENU ---
export const getMenuItems = async (): Promise<MenuItem[]> => {
  const q = query(collection(db, 'menuItems'), where('isAvailable', '==', true));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as MenuItem));
};

export const getAllMenuItemsAdmin = async (): Promise<MenuItem[]> => {
  const q = query(collection(db, 'menuItems'));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as MenuItem));
};

export const addMenuItem = async (item: Omit<MenuItem, 'id'>) => {
  return addDoc(collection(db, 'menuItems'), item);
};

export const updateMenuItem = async (id: string, data: Partial<MenuItem>) => {
  return updateDoc(doc(db, 'menuItems', id), data);
};

// --- SLOTS & ORDERS ---

// Ensure a slot document exists
export const ensureSlotExists = async (slotId: string, startTime: Date) => {
  const slotRef = doc(db, 'timeSlots', slotId);
  // We use setDoc with merge: true to avoid overwriting if it exists, or transaction.
  // Ideally this is done via transaction during booking, but creating slots ahead of time is better.
  await setDoc(slotRef, {
    id: slotId,
    startTime: Timestamp.fromDate(startTime),
    maxOrders: MAX_ORDERS_PER_SLOT,
    // currentOrders will not be overwritten if it exists due to merge logic check in transaction usually, 
    // but here we just initialize if missing. 
    // A safer way is to let the transaction handle creation if missing.
  }, { merge: true });
};

export const createOrder = async (
  userId: string, 
  userEmail: string, 
  items: MenuItem[], 
  quantities: Record<string, number>,
  slotId: string,
  slotDate: Date
): Promise<string> => {

  const totalAmount = items.reduce((sum, item) => sum + (item.price * quantities[item.id]), 0);
  const orderItems = items.map(item => ({
    menuItemId: item.id,
    name: item.name,
    price: item.price,
    quantity: quantities[item.id]
  }));

  try {
    const orderId = await runTransaction(db, async (transaction) => {
      const slotRef = doc(db, 'timeSlots', slotId);
      const slotDoc = await transaction.get(slotRef);

      let currentOrders = 0;
      let maxOrders = MAX_ORDERS_PER_SLOT;
      let status = 'available';

      if (slotDoc.exists()) {
        const slotData = slotDoc.data() as TimeSlot;
        currentOrders = slotData.currentOrders || 0;
        maxOrders = slotData.maxOrders;
        status = slotData.status;
      }

      if (status !== 'available' || currentOrders >= maxOrders) {
        throw new Error("SLOT_FULL");
      }

      // Create or Update Slot
      transaction.set(slotRef, {
        id: slotId,
        startTime: Timestamp.fromDate(slotDate),
        maxOrders,
        currentOrders: currentOrders + 1,
        status: (currentOrders + 1 >= maxOrders) ? 'full' : 'available'
      }, { merge: true });

      // Create Order
      const newOrderRef = doc(collection(db, 'orders'));
      const newOrder: Omit<Order, 'id'> = {
        userId,
        userEmail,
        items: orderItems,
        totalAmount,
        status: OrderStatus.CONFIRMED,
        scheduledTime: Timestamp.fromDate(slotDate),
        slotId,
        createdAt: Timestamp.now()
      };

      transaction.set(newOrderRef, newOrder);
      return newOrderRef.id;
    });
    return orderId;
  } catch (e) {
    console.error("Transaction failed: ", e);
    throw e;
  }
};

// --- USER ORDERS ---
export const subscribeToUserOrders = (userId: string, callback: (orders: Order[]) => void) => {
  const q = query(
    collection(db, 'orders'), 
    where('userId', '==', userId), 
    orderBy('createdAt', 'desc')
  );
  return onSnapshot(q, (snapshot) => {
    const orders = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Order));
    callback(orders);
  });
};

// --- ADMIN ---
export const subscribeToAllOrders = (callback: (orders: Order[]) => void) => {
  // Limited to last 100 for performance in this demo
  const q = query(
    collection(db, 'orders'), 
    orderBy('createdAt', 'desc')
  );
  return onSnapshot(q, (snapshot) => {
    const orders = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Order));
    callback(orders);
  });
};

export const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
  return updateDoc(doc(db, 'orders', orderId), { status });
};

