import React, { createContext, useContext, useEffect, useState } from 'react';
import { User, onAuthStateChanged, signInWithPopup, signOut } from 'firebase/auth';
import { auth, googleProvider, db } from '../firebase';
import { ADMIN_EMAIL } from '../constants';
import { UserProfile, UserRole } from '../types';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

interface AuthContextType {
  user: UserProfile | null;
  loading: boolean;
  signInWithGoogle: () => Promise<void>;
  logout: () => Promise<void>;
  isAdmin: boolean;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // Sync user to Firestore
        const userRef = doc(db, 'users', firebaseUser.uid);
        const userSnap = await getDoc(userRef);

        let role = UserRole.USER;
        if (firebaseUser.email === ADMIN_EMAIL) {
          role = UserRole.ADMIN;
        }

        const profile: UserProfile = {
          uid: firebaseUser.uid,
          email: firebaseUser.email || '',
          displayName: firebaseUser.displayName || 'User',
          role,
          createdAt: userSnap.exists() ? userSnap.data().createdAt : serverTimestamp(),
        };

        if (!userSnap.exists()) {
          await setDoc(userRef, profile);
        }

        setUser(profile);
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error("Login failed", error);
    }
  };

  const logout = () => signOut(auth);

  const isAdmin = user?.role === UserRole.ADMIN;

  return (
    <AuthContext.Provider value={{ user, loading, signInWithGoogle, logout, isAdmin }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { MenuItem } from '../types';

interface CartContextType {
  items: MenuItem[];
  quantities: Record<string, number>;
  addToCart: (item: MenuItem) => void;
  removeFromCart: (itemId: string) => void;
  updateQuantity: (itemId: string, delta: number) => void;
  clearCart: () => void;
  totalItems: number;
  totalPrice: number;
  isCartOpen: boolean;
  toggleCart: () => void;
}

const CartContext = createContext<CartContextType>({} as CartContextType);

export const useCart = () => useContext(CartContext);

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [items, setItems] = useState<MenuItem[]>([]);
  const [quantities, setQuantities] = useState<Record<string, number>>({});
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Load from local storage
  useEffect(() => {
    const savedCart = localStorage.getItem('noir_cart');
    if (savedCart) {
      const { items: savedItems, quantities: savedQuantities } = JSON.parse(savedCart);
      setItems(savedItems);
      setQuantities(savedQuantities);
    }
  }, []);

  // Save to local storage
  useEffect(() => {
    localStorage.setItem('noir_cart', JSON.stringify({ items, quantities }));
  }, [items, quantities]);

  const addToCart = (item: MenuItem) => {
    if (!quantities[item.id]) {
      setItems([...items, item]);
      setQuantities({ ...quantities, [item.id]: 1 });
    } else {
      setQuantities({ ...quantities, [item.id]: quantities[item.id] + 1 });
    }
    setIsCartOpen(true);
  };

  const removeFromCart = (itemId: string) => {
    setItems(items.filter(i => i.id !== itemId));
    const newQuantities = { ...quantities };
    delete newQuantities[itemId];
    setQuantities(newQuantities);
  };

  const updateQuantity = (itemId: string, delta: number) => {
    const newQty = (quantities[itemId] || 0) + delta;
    if (newQty <= 0) {
      removeFromCart(itemId);
    } else {
      setQuantities({ ...quantities, [itemId]: newQty });
    }
  };

  const clearCart = () => {
    setItems([]);
    setQuantities({});
  };

  const toggleCart = () => setIsCartOpen(!isCartOpen);

  const totalItems = Object.values(quantities).reduce((a, b) => a + b, 0);
  const totalPrice = items.reduce((sum, item) => sum + (item.price * (quantities[item.id] || 0)), 0);

  return (
    <CartContext.Provider value={{ 
      items, quantities, addToCart, removeFromCart, updateQuantity, 
      clearCart, totalItems, totalPrice, isCartOpen, toggleCart 
    }}>
      {children}
    </CartContext.Provider>
  );
};

