import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { Loader2, ArrowLeft } from 'lucide-react';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState('');

  if (!user) return <Navigate to={ROUTES.LOGIN} />;
  if (items.length === 0) return <Navigate to={ROUTES.HOME} />;

  const slots = generateTimeSlots();

  const handlePlaceOrder = async () => {
    if (!selectedSlot) return;
    setIsProcessing(true);
    setError('');

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot
      );
      clearCart();
      navigate(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setError("The selected time slot just filled up. Please choose another.");
      } else {
        setError("Something went wrong. Please try again.");
      }
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto">
      <button onClick={() => navigate(-1)} className="flex items-center text-sm text-gray-500 hover:text-noir mb-6">
        <ArrowLeft className="w-4 h-4 mr-1" /> Back to menu
      </button>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        {/* Slot Selection */}
        <div>
          <h2 className="text-2xl font-serif font-bold text-noir mb-6">Choose Pickup Time</h2>
          <div className="space-y-6">
             {/* Simple date grouping could happen here, simpler flat list for MVP */}
             <div className="grid grid-cols-3 gap-3 max-h-96 overflow-y-auto p-1">
               {slots.map((slot) => (
                 <button
                   key={slot.toISOString()}
                   onClick={() => setSelectedSlot(slot)}
                   className={`px-2 py-3 text-sm rounded-lg border text-center transition-all ${
                     selectedSlot === slot
                       ? 'bg-noir text-white border-noir shadow-md'
                       : 'bg-white border-gray-200 text-gray-700 hover:border-gray-400 hover:bg-gray-50'
                   }`}
                 >
                   {formatTime(slot)}
                 </button>
               ))}
             </div>
             {error && <p className="text-red-600 text-sm bg-red-50 p-3 rounded-md">{error}</p>}
          </div>
        </div>

        {/* Order Summary */}
        <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm h-fit">
          <h3 className="text-lg font-bold text-noir mb-4">Order Summary</h3>
          <ul className="divide-y divide-gray-100 mb-6">
            {items.map(item => (
              <li key={item.id} className="py-3 flex justify-between text-sm">
                <span className="text-gray-600">{quantities[item.id]}x {item.name}</span>
                <span className="font-mono">{formatPrice(item.price * quantities[item.id])}</span>
              </li>
            ))}
          </ul>

          <div className="flex justify-between items-center border-t border-gray-100 pt-4 mb-6">
            <span className="font-bold text-gray-900">Total</span>
            <span className="font-bold font-mono text-xl">{formatPrice(totalPrice)}</span>
          </div>

          <button
            onClick={handlePlaceOrder}
            disabled={!selectedSlot || isProcessing}
            className="w-full flex justify-center items-center px-6 py-4 border border-transparent rounded-lg shadow-sm text-base font-medium text-white bg-noir hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Confirm Order'}
          </button>

          {!selectedSlot && <p className="text-xs text-center text-gray-400 mt-2">Please select a time slot</p>}
        </div>
      </div>
    </div>
  );
};

