           >
             Active ({activeOrders.length})
           </button>
           <button 
             onClick={() => setActiveTab('completed')}
             className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'completed' ? 'bg-noir text-white shadow-sm' : 'text-gray-500 hover:text-gray-900'}`}
           >
             History
           </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {displayOrders.map(order => (
          <div key={order.id} className={`bg-white border rounded-xl p-6 shadow-sm transition-all ${order.status === OrderStatus.READY ? 'border-green-500 ring-1 ring-green-500' : 'border-gray-200'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <span className="font-mono text-xs text-gray-400">#{order.id.slice(0, 6)}</span>
                <h3 className="font-bold text-lg text-noir">{order.userEmail.split('@')[0]}</h3>
