              <div className="text-right">
                <p className="text-xl font-mono font-bold">{formatTime(order.scheduledTime)}</p>
                <p className="text-xs text-gray-500 uppercase tracking-wide">Pickup Time</p>
              </div>
            </div>

            <div className="bg-gray-50 rounded-lg p-3 mb-4 space-y-1">
              {order.items.map((item, i) => (
                <div key={i} className="flex justify-between text-sm">
                  <span className="font-medium text-gray-800">{item.quantity}x {item.name}</span>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-2 mt-4">
               {order.status === OrderStatus.CONFIRMED && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-yellow-100 text-yellow-800 py-2 rounded-lg text-sm font-bold hover:bg-yellow-200 transition-colors"
                 >
                   <Utensils className="w-4 h-4" /> Start Cooking
                 </button>
               )}
               {order.status === OrderStatus.PREPARING && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-green-100 text-green-800 py-2 rounded-lg text-sm font-bold hover:bg-green-200 transition-colors"
                 >
                   <CheckCircle className="w-4 h-4" /> Mark Ready
                 </button>
               )}
               {order.status === OrderStatus.READY && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-gray-100 text-gray-800 py-2 rounded-lg text-sm font-bold hover:bg-gray-200 transition-colors"
                 >
                   <CheckCircle className="w-4 h-4" /> Complete
                 </button>
               )}

               {/* Cancellation available for active orders */}
               {(order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                   className="col-span-2 mt-2 flex items-center justify-center gap-2 text-red-600 py-2 rounded-lg text-xs font-medium hover:bg-red-50 transition-colors"
                 >
                   Cancel Order
                 </button>
