import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  User, 
  onAuthStateChanged, 
  signInWithPopup, 
  signOut, 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  updateProfile
} from 'firebase/auth';
import { auth, googleProvider, db } from '../firebase';
import { ADMIN_EMAIL } from '../constants';
import { UserProfile, UserRole } from '../types';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

interface AuthContextType {
  user: UserProfile | null;
  loading: boolean;
  signInWithGoogle: () => Promise<void>;
  loginWithEmail: (email: string, password: string) => Promise<void>;
  signupWithEmail: (email: string, password: string, name: string) => Promise<void>;
  logout: () => Promise<void>;
  isAdmin: boolean;
  error: string | null;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        try {
          // Sync user to Firestore
          const userRef = doc(db, 'users', firebaseUser.uid);
          const userSnap = await getDoc(userRef);

          let role = UserRole.USER;
          if (firebaseUser.email === ADMIN_EMAIL) {
            role = UserRole.ADMIN;
          }

          // Define profile data
          const profile: UserProfile = {
            uid: firebaseUser.uid,
            email: firebaseUser.email || '',
            displayName: firebaseUser.displayName || 'User',
            role,
            createdAt: userSnap.exists() ? userSnap.data().createdAt : serverTimestamp(),
          };

          // If new user (or just created via Auth), ensure doc exists
          if (!userSnap.exists()) {
            await setDoc(userRef, profile);
          }

          setUser(profile);
          setError(null);
        } catch (err: any) {
          console.error("Error syncing user profile:", err);
          // Don't block app usage, but log it
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleError = (err: any) => {
    console.error("Auth Error:", err);
    if (err.code === 'auth/api-key-not-valid.-please-pass-a-valid-api-key.') {
      setError("Configuration Error: Invalid Firebase API Key.");
    } else if (err.code === 'auth/popup-closed-by-user') {
      setError("Sign in cancelled.");
    } else if (err.code === 'auth/unauthorized-domain') {
      setError(`Domain Unauthorized: Add '${window.location.hostname}' to Firebase Console > Auth > Settings > Authorized Domains.`);
    } else if (err.code === 'auth/email-already-in-use') {
      setError("This email is already registered. Please login.");
    } else if (err.code === 'auth/wrong-password' || err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
      setError("Invalid email or password.");
    } else {
      setError(err.message || "Authentication failed.");
    }
    throw err;
  };

  const signInWithGoogle = async () => {
    setError(null);
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (err: any) {
      handleError(err);
    }
  };

  const loginWithEmail = async (email: string, password: string) => {
    setError(null);
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (err: any) {
      handleError(err);
    }
  };

  const signupWithEmail = async (email: string, password: string, name: string) => {
    setError(null);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      // Update Auth Profile
      await updateProfile(userCredential.user, {
        displayName: name
      });
      // Trigger the onAuthStateChanged listener to handle Firestore sync
    } catch (err: any) {
      handleError(err);
    }
  };

  const logout = () => signOut(auth);

  const isAdmin = user?.role === UserRole.ADMIN;

  return (
    <AuthContext.Provider value={{ user, loading, signInWithGoogle, loginWithEmail, signupWithEmail, logout, isAdmin, error }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { ROUTES } from '../constants';
import { AlertTriangle, User, Mail, Lock, Shield } from 'lucide-react';

type Tab = 'login' | 'signup' | 'admin';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<Tab>('login');

  // Form States
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;
  if (user) return <Navigate to={ROUTES.HOME} />;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');
    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        if (!name) throw new Error("Name is required");
        await signupWithEmail(email, password, name);
      } else {
        // Both Login and Admin use the same auth method, logic is handled in context
        await loginWithEmail(email, password);
      }
      navigate(ROUTES.HOME);
    } catch (err: any) {
      // Error is set in context, but we catch here to stop loading state
      setLocalError(err.message || "Action failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      navigate(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">

        {/* Header Section */}
        <div className="bg-noir p-6 text-center">
          <h1 className="text-2xl font-serif font-bold text-white mb-2">
            {activeTab === 'signup' ? 'Create Account' : activeTab === 'admin' ? 'Admin Portal' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 text-sm">
            {activeTab === 'signup' ? 'Join us for premium dining' : activeTab === 'admin' ? 'Staff access only' : 'Sign in to your account'}
          </p>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-100">
          <button
            onClick={() => { setActiveTab('login'); setLocalError(''); }}
            className={`flex-1 py-4 text-sm font-medium transition-colors ${activeTab === 'login' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Login
          </button>
          <button
            onClick={() => { setActiveTab('signup'); setLocalError(''); }}
            className={`flex-1 py-4 text-sm font-medium transition-colors ${activeTab === 'signup' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Sign Up
          </button>
          <button
            onClick={() => { setActiveTab('admin'); setLocalError(''); }}
            className={`flex-1 py-4 text-sm font-medium transition-colors ${activeTab === 'admin' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Admin
          </button>
        </div>

        <div className="p-8">
          {displayError && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-lg flex items-start text-left animate-fade-in">
              <AlertTriangle className="w-5 h-5 text-red-500 mr-3 flex-shrink-0 mt-0.5" />
              <p className="text-sm text-red-700 break-words">{displayError}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {activeTab === 'signup' && (
              <div className="relative">
                <User className="absolute left-3 top-3.5 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  placeholder="Full Name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-noir focus:border-transparent outline-none transition-all"
                  required
                />
              </div>
            )}

            <div className="relative">
              <div className="absolute left-3 top-3.5 w-5 h-5 text-gray-400 flex items-center justify-center">
                 {activeTab === 'admin' ? <Shield className="w-4 h-4" /> : <Mail className="w-4 h-4" />}
              </div>
              <input
                type="email"
                placeholder={activeTab === 'admin' ? "admin@canteen.com" : "Email Address"}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-noir focus:border-transparent outline-none transition-all"
                required
              />
            </div>

            <div className="relative">
              <Lock className="absolute left-3 top-3.5 w-5 h-5 text-gray-400" />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-noir focus:border-transparent outline-none transition-all"
                required
                minLength={6}
              />
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-noir text-white font-bold py-3 rounded-lg hover:bg-gray-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed mt-2"
            >
              {isSubmitting ? 'Please wait...' : activeTab === 'signup' ? 'Create Account' : activeTab === 'admin' ? 'Admin Login' : 'Sign In'}
            </button>
          </form>

          {activeTab !== 'admin' && (
            <>
              <div className="relative my-8">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-gray-200"></div>
                </div>
                <div className="relative flex justify-center text-sm">
                  <span className="px-2 bg-white text-gray-500">Or continue with</span>
                </div>
              </div>

              <button
                type="button"
                onClick={handleGoogleLogin}
                className="w-full flex items-center justify-center gap-3 bg-white border border-gray-300 rounded-lg px-6 py-3 text-gray-700 font-medium hover:bg-gray-50 hover:border-gray-400 transition-all shadow-sm"
              >
                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5" />
                Google
              </button>
            </>
          )}

          <p className="mt-8 text-xs text-center text-gray-400">
            By continuing, you agree to our Terms of Service and Privacy Policy.
          </p>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search, ShieldAlert, Terminal } from 'lucide-react';

export const Home: React.FC = () => {
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchMenu = async () => {
      try {
        const data = await getMenuItems();
        if (data.length === 0) {
          // Attempt to seed, but if rules prevent write, this will also fail, handled by catch
          try {
            await seedMenu();
            const seededData = await getMenuItems();
            setItems(seededData);
          } catch (seedErr) {
            // Use empty list if seed fails, likely due to permission too
            setItems([]);
          }
        } else {
          setItems(data);
        }
      } catch (err: any) {
        console.error("Failed to load menu", err);
        if (err.code === 'permission-denied' || err.message.includes('permission')) {
          setError("permission-denied");
        } else {
          setError("Failed to load menu items. Please try again later.");
        }
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, []);

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-80 bg-gray-200 rounded-xl"></div>
        ))}
      </div>
    );
  }

  // Handle Missing Permissions (Common first-run error)
  if (error === 'permission-denied') {
    return (
      <div className="max-w-2xl mx-auto mt-10 bg-white border-l-4 border-yellow-500 rounded-r-lg shadow-md p-6">
        <div className="flex items-start">
          <ShieldAlert className="w-8 h-8 text-yellow-500 mr-4 flex-shrink-0" />
          <div className="flex-1">
            <h3 className="text-lg font-bold text-gray-900">Firestore Rules Setup Required</h3>
            <p className="text-gray-600 mt-1 mb-4">
              The app cannot read the menu items. This usually means the Firestore Security Rules haven't been configured in the Firebase Console.
            </p>

