import { Search, AlertCircle } from 'lucide-react';

export const Home: React.FC = () => {
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMockData, setUsingMockData] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        // If data is empty, try seeding (only works if permissions allow)
        if (data.length === 0) {
          try {
            await seedMenu();
            data = await getMenuItems();
          } catch (e) {
            // Seeding failed, likely permissions. getMenuItems probably returned mock data in catch block or []
            // If getMenuItems returned [], we might want to manually fetch it again if the service didn't mock it?
            // But our updated service mocks it on error.
          }
        }

        // Detect if we are getting mock data (based on ID or description)
        if (data.length > 0 && data[0].id.startsWith('mock')) {
          setUsingMockData(true);
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, []);

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-80 bg-gray-200 rounded-xl"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Demo Data Warning */}
      {usingMockData && (
        <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-lg flex items-start text-sm">
          <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
          <p>
            <strong>Demo Mode:</strong> We couldn't fetch live data (Firestore permissions missing). Showing sample menu items.
            To fix, configure your Firestore Security Rules in the Firebase Console.
          </p>
        </div>
      )}

      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-serif font-bold text-noir">Today's Menu</h1>
          <p className="text-gray-500 mt-1">Fresh, seasonal, and ready when you are.</p>
        </div>

        <div className="flex items-center gap-2 bg-white border border-gray-200 rounded-lg p-2 shadow-sm w-full md:w-auto">
          <Search className="w-5 h-5 text-gray-400" />
          <input 
            type="text" 
            placeholder="Search items..." 
            className="outline-none text-sm bg-transparent flex-grow md:w-64"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Categories */}
      <div className="flex overflow-x-auto gap-2 pb-2 scrollbar-hide">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-4 py-2 rounded-full text-sm font-medium transition-colors whitespace-nowrap capitalize ${
              activeCategory === cat 
                ? 'bg-noir text-white' 
                : 'bg-white border border-gray-200 text-gray-600 hover:border-gray-400'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredItems.map(item => (
            <MenuItemCard key={item.id} item={item} />
          ))}
        </div>
      ) : (
        <div className="text-center py-20">
            <>
              <p className="text-gray-500 text-lg">No items found.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); }}
                className="mt-4 text-noir underline font-medium"
              >
                Clear filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

