import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  User, 
  onAuthStateChanged, 
  signInWithPopup, 
  signOut, 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  updateProfile
} from 'firebase/auth';
import { auth, googleProvider, db } from '../firebase';
import { ADMIN_EMAIL } from '../constants';
import { UserProfile, UserRole } from '../types';
import { doc, getDoc, setDoc, serverTimestamp, Timestamp } from 'firebase/firestore';

interface AuthContextType {
  user: UserProfile | null;
  loading: boolean;
  signInWithGoogle: () => Promise<void>;
  loginWithEmail: (email: string, password: string) => Promise<void>;
  signupWithEmail: (email: string, password: string, name: string) => Promise<void>;
  logout: () => Promise<void>;
  isAdmin: boolean;
  error: string | null;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        try {
          // Sync user to Firestore
          const userRef = doc(db, 'users', firebaseUser.uid);
          const userSnap = await getDoc(userRef);

          let role = UserRole.USER;
          if (firebaseUser.email === ADMIN_EMAIL) {
            role = UserRole.ADMIN;
          }

          // Define profile data
          // FIX: Use Timestamp.now() for local state to match UserProfile interface. 
          // serverTimestamp() is for writes only and returns a FieldValue, not a Timestamp.
          const profile: UserProfile = {
            uid: firebaseUser.uid,
            email: firebaseUser.email || '',
            displayName: firebaseUser.displayName || 'User',
            role,
            createdAt: userSnap.exists() ? userSnap.data().createdAt : Timestamp.now(),
          };

          // If new user (or just created via Auth), ensure doc exists
          if (!userSnap.exists()) {
            await setDoc(userRef, profile);
          }

          setUser(profile);
          setError(null);
        } catch (err: any) {
          console.error("Error syncing user profile:", err);
          // Don't block app usage, but log it
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleError = (err: any) => {
    console.error("Auth Error:", err.code, err.message);
    if (err.code === 'auth/api-key-not-valid.-please-pass-a-valid-api-key.') {
      setError("Configuration Error: Invalid Firebase API Key.");
    } else if (err.code === 'auth/popup-closed-by-user') {
      setError("Sign in cancelled.");
    } else if (err.code === 'auth/unauthorized-domain') {
      setError(`Domain Unauthorized: Add '${window.location.hostname}' to Firebase Console > Auth > Settings > Authorized Domains.`);
    } else if (err.code === 'auth/email-already-in-use') {
      setError("This email is already registered. Please login.");
    } else if (err.code === 'auth/wrong-password' || err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
      setError("Account not found or password incorrect. Please Sign Up if you are new.");
    } else {
      setError(err.message || "Authentication failed.");
    }
    throw err;
  };

  const signInWithGoogle = async () => {
    setError(null);
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (err: any) {
      handleError(err);
    }
  };

  const loginWithEmail = async (email: string, password: string) => {
    setError(null);
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (err: any) {
      handleError(err);
    }
  };

  const signupWithEmail = async (email: string, password: string, name: string) => {
    setError(null);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      // Update Auth Profile
      await updateProfile(userCredential.user, {
        displayName: name
      });
      // Trigger the onAuthStateChanged listener to handle Firestore sync
    } catch (err: any) {
      handleError(err);
    }
  };

  const logout = () => signOut(auth);

  const isAdmin = user?.role === UserRole.ADMIN;

  return (
    <AuthContext.Provider value={{ user, loading, signInWithGoogle, loginWithEmail, signupWithEmail, logout, isAdmin, error }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { subscribeToAllOrders, updateOrderStatus } from '../services/firestoreService';
import { Order, OrderStatus, UserRole } from '../types';
import { formatTime, formatPrice } from '../utils/formatters';
import { Navigate } from 'react-router-dom';
import { ROUTES } from '../constants';
import { CheckCircle, Utensils } from 'lucide-react';

export const AdminDashboard: React.FC = () => {
  const { user, isAdmin } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeTab, setActiveTab] = useState<'active' | 'completed'>('active');

  useEffect(() => {
    if (!isAdmin) return;
    const unsubscribe = subscribeToAllOrders((data) => {
      setOrders(data);
    });
    return () => unsubscribe();
  }, [isAdmin]);

  if (!user || !isAdmin) return <Navigate to={ROUTES.HOME} />;

  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const activeOrders = orders.filter(o => [OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));

  const displayOrders = activeTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-serif font-bold text-noir">Kitchen Dashboard</h1>
        <div className="flex gap-2 bg-white p-1 rounded-lg border border-gray-200">
           <button 
             onClick={() => setActiveTab('active')}
             className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'active' ? 'bg-noir text-white shadow-sm' : 'text-gray-500 hover:text-gray-900'}`}
           >
             Active ({activeOrders.length})
           </button>
           <button 
             onClick={() => setActiveTab('completed')}
             className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'completed' ? 'bg-noir text-white shadow-sm' : 'text-gray-500 hover:text-gray-900'}`}
           >
             History
           </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {displayOrders.map(order => (
          <div key={order.id} className={`bg-white border rounded-xl p-6 shadow-sm transition-all ${order.status === OrderStatus.READY ? 'border-green-500 ring-1 ring-green-500' : 'border-gray-200'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <span className="font-mono text-xs text-gray-400">#{order.id.slice(0, 6)}</span>
                <h3 className="font-bold text-lg text-noir">{order.userEmail.split('@')[0]}</h3>
              </div>
              <div className="text-right">
                <p className="text-xl font-mono font-bold">{formatTime(order.scheduledTime)}</p>
                <p className="text-xs text-gray-500 uppercase tracking-wide">Pickup Time</p>
              </div>
            </div>

            <div className="bg-gray-50 rounded-lg p-3 mb-4 space-y-1">
              {order.items.map((item, i) => (
                <div key={i} className="flex justify-between text-sm">
                  <span className="font-medium text-gray-800">{item.quantity}x {item.name}</span>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-2 mt-4">
               {order.status === OrderStatus.CONFIRMED && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-yellow-100 text-yellow-800 py-2 rounded-lg text-sm font-bold hover:bg-yellow-200 transition-colors"
                 >
                   <Utensils className="w-4 h-4" /> Start Cooking
                 </button>
               )}
               {order.status === OrderStatus.PREPARING && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-green-100 text-green-800 py-2 rounded-lg text-sm font-bold hover:bg-green-200 transition-colors"
                 >
                   <CheckCircle className="w-4 h-4" /> Mark Ready
                 </button>
               )}
               {order.status === OrderStatus.READY && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                   className="col-span-2 flex items-center justify-center gap-2 bg-gray-100 text-gray-800 py-2 rounded-lg text-sm font-bold hover:bg-gray-200 transition-colors"
                 >
                   <CheckCircle className="w-4 h-4" /> Complete
                 </button>
               )}

               {/* Cancellation available for active orders */}
               {(order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                 <button 
                   onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                   className="col-span-2 mt-2 flex items-center justify-center gap-2 text-red-600 py-2 rounded-lg text-xs font-medium hover:bg-red-50 transition-colors"
                 >
                   Cancel Order
                 </button>
               )}
            </div>

            <div className="mt-4 pt-4 border-t border-gray-100 text-center">
              <span className={`text-xs font-bold uppercase tracking-wider px-2 py-1 rounded-sm ${
                order.status === OrderStatus.READY ? 'bg-green-100 text-green-800' : 
                order.status === OrderStatus.PREPARING ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100 text-gray-500'
              }`}>
                {order.status}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

