import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search, AlertCircle } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMockData, setUsingMockData] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Ref to prevent double-execution in React Strict Mode
  const isInitialized = useRef(false);

  useEffect(() => {
    // Prevent running twice in development
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        // Only attempt to seed if database is empty AND user is logged in
        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              // Fetch again to get the IDs generated by Firestore
              data = await getMenuItems();
            } catch (e) {
              console.warn("Seeding failed despite being logged in (check Admin role rules)");
              setUsingMockData(true);
              data = MOCK_MENU_ITEMS;
            }
          } else {
             // Not logged in? Just use mock data for display.
             // We don't consider this an error worthy of an alert, just normal demo state.
             setUsingMockData(true);
             data = MOCK_MENU_ITEMS;
          }
        }

        // Detect if we are getting mock data from the service fallback
        if (data.length > 0 && data[0].id.startsWith('mock')) {
          setUsingMockData(true);
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]); // Re-run if user logs in

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-80 bg-gray-200 rounded-xl"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Demo Data Warning - Only show if explicit error, or if we want to inform user */}
      {usingMockData && (
        <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-lg flex items-start text-sm animate-fade-in">
          <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
          <p>
            <strong>Demo Mode:</strong> Displaying sample menu items. 
            {!user ? " Log in as Admin to manage the real menu." : " Configure Firestore rules to enable real data."}
          </p>
        </div>
      )}

      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-serif font-bold text-noir">Today's Menu</h1>
          <p className="text-gray-500 mt-1">Fresh, seasonal, and ready when you are.</p>
        </div>

        <div className="flex items-center gap-2 bg-white border border-gray-200 rounded-lg p-2 shadow-sm w-full md:w-auto">
          <Search className="w-5 h-5 text-gray-400" />
          <input 
            type="text" 
            placeholder="Search items..." 
            className="outline-none text-sm bg-transparent flex-grow md:w-64"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Categories */}
      <div className="flex overflow-x-auto gap-2 pb-2 scrollbar-hide">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-4 py-2 rounded-full text-sm font-medium transition-colors whitespace-nowrap capitalize ${
              activeCategory === cat 
                ? 'bg-noir text-white' 
                : 'bg-white border border-gray-200 text-gray-600 hover:border-gray-400'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredItems.map(item => (
            <MenuItemCard key={item.id} item={item} />
          ))}
        </div>
      ) : (
        <div className="text-center py-20">
            <>
              <p className="text-gray-500 text-lg">No items found.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); }}
                className="mt-4 text-noir underline font-medium"
              >
                Clear filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- HELPER FUNCTIONS ---

    // Check if user is logged in
    function isAuthenticated() {
      return request.auth != null;
    }

    // Check if the user is accessing their own data
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }

    // Check if the user is an Admin
    // We check the specific email (hardcoded in constants.ts) OR the role in the users collection
    function isAdmin() {
      return isAuthenticated() && (
        request.auth.token.email == 'admin@canteen.com' || 
        get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'ADMIN'
      );
    }

    // --- COLLECTION RULES ---

    // 1. Users Collection
    // - Users can read and write their own profile
    // - Admins can read all profiles (useful for dashboard)
    match /users/{userId} {
      allow read: if isOwner(userId) || isAdmin();
      allow create: if isOwner(userId);
      allow update: if isOwner(userId) || isAdmin();
    }

    // 2. Menu Items
    // - Public Read: Everyone needs to see the menu
    // - Admin Write: Only admin can add/edit items
    match /menuItems/{itemId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    // 3. Orders
    // - Read: Admin sees all, Users see only their own
    // - Create: Authenticated users can create orders (must match their UID)
    // - Update: Only Admin can update status (e.g., to READY or COMPLETED)
    match /orders/{orderId} {
      allow read: if isAdmin() || (isAuthenticated() && resource.data.userId == request.auth.uid);
      allow create: if isAuthenticated() && request.resource.data.userId == request.auth.uid;
      allow update: if isAdmin(); 
    }

    // 4. Time Slots
    // - Read: Public (to show availability)
    // - Write: Authenticated users need to write here to increment 'currentOrders' 
    //   during the checkout transaction.
    match /timeSlots/{slotId} {
      allow read: if true;
      allow write: if isAuthenticated();
    }
  }
}

