import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { subscribeToAllOrders, updateOrderStatus, getAllMenuItemsAdmin, addMenuItem, updateMenuItem } from '../services/firestoreService';
import { Order, OrderStatus, MenuItem, ProductCategory } from '../types';
import { formatTime, formatPrice } from '../utils/formatters';
import { Navigate } from 'react-router-dom';
import { ROUTES } from '../constants';
import { Check, Utensils, Plus, Image as ImageIcon, X, Coffee, List, ChevronRight } from 'lucide-react';

export const AdminDashboard: React.FC = () => {
  const { user, isAdmin } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);

  const [view, setView] = useState<'kitchen' | 'menu'>('kitchen');
  const [activeOrderTab, setActiveOrderTab] = useState<'active' | 'completed'>('active');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [loadingMenu, setLoadingMenu] = useState(false);

  const [newItem, setNewItem] = useState<Partial<MenuItem>>({
    name: '',
    description: '',
    price: 0,
    category: ProductCategory.Lunch,
    imageUrl: '',
    preparationTime: 10,
    isAvailable: true
  });

  useEffect(() => {
    if (!isAdmin) return;
    const unsubscribe = subscribeToAllOrders((data) => {
      setOrders(data);
    });
    return () => unsubscribe();
  }, [isAdmin]);

  useEffect(() => {
    if (view === 'menu' && isAdmin) {
      setLoadingMenu(true);
      getAllMenuItemsAdmin()
        .then(setMenuItems)
        .finally(() => setLoadingMenu(false));
    }
  }, [view, isAdmin, isAddingItem]);

  if (!user || !isAdmin) return <Navigate to={ROUTES.HOME} />;

  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const handleToggleAvailability = async (id: string, currentStatus: boolean) => {
    try {
      await updateMenuItem(id, { isAvailable: !currentStatus });
      setMenuItems(prev => prev.map(item => item.id === id ? { ...item, isAvailable: !currentStatus } : item));
    } catch (e) {
      console.error("Failed to toggle availability", e);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addMenuItem(newItem as MenuItem);
      setIsAddingItem(false);
      setNewItem({
        name: '',
        description: '',
        price: 0,
        category: ProductCategory.Lunch,
        imageUrl: '',
        preparationTime: 10,
        isAvailable: true
      });
    } catch (e) {
      console.error("Failed to add item", e);
      alert("Failed to add item. Check permissions.");
    }
  };

  const activeOrders = orders.filter(o => [OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));
  const displayOrders = activeOrderTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-12 pb-20">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 border-b border-black pb-8">
        <div>
           <h1 className="text-4xl font-serif font-bold text-noir">Command Center</h1>
        </div>

        <div className="flex border border-black p-1">
          <button
            onClick={() => setView('kitchen')}
            className={`flex items-center px-6 py-2 text-xs font-bold uppercase tracking-widest transition-all ${view === 'kitchen' ? 'bg-noir text-white' : 'text-gray-400 hover:text-noir'}`}
          >
            Kitchen
          </button>
          <button
            onClick={() => setView('menu')}
            className={`flex items-center px-6 py-2 text-xs font-bold uppercase tracking-widest transition-all ${view === 'menu' ? 'bg-noir text-white' : 'text-gray-400 hover:text-noir'}`}
          >
            Menu
          </button>
        </div>
      </div>

      {view === 'kitchen' && (
        <div className="space-y-8 animate-fade-in">
          <div className="flex gap-8 border-b border-gray-200">
             <button 
               onClick={() => setActiveOrderTab('active')}
               className={`pb-4 text-sm font-bold uppercase tracking-widest transition-colors ${activeOrderTab === 'active' ? 'border-b-2 border-noir text-noir' : 'border-transparent text-gray-400 hover:text-noir'}`}
             >
               Live Orders ({activeOrders.length})
             </button>
             <button 
               onClick={() => setActiveOrderTab('completed')}
               className={`pb-4 text-sm font-bold uppercase tracking-widest transition-colors ${activeOrderTab === 'completed' ? 'border-b-2 border-noir text-noir' : 'border-transparent text-gray-400 hover:text-noir'}`}
             >
               Archive
             </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {displayOrders.length === 0 && (
              <div className="col-span-full text-center py-24 border border-dashed border-gray-300">
                <Coffee className="w-8 h-8 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500 font-mono text-sm">No orders in queue.</p>
              </div>
            )}

            {displayOrders.map(order => (
              <div key={order.id} className={`bg-white border p-6 transition-all relative ${order.status === OrderStatus.READY ? 'border-black ring-1 ring-black' : 'border-gray-200'}`}>
                {order.status === OrderStatus.READY && (
                    <div className="absolute top-0 left-0 right-0 bg-black text-white text-xs font-bold text-center py-1 uppercase tracking-widest">Ready for Pickup</div>
                )}

                <div className={`flex justify-between items-start mb-6 ${order.status === OrderStatus.READY ? 'mt-4' : ''}`}>
                  <div>
                    <h3 className="font-bold text-xl text-noir">{order.userEmail.split('@')[0]}</h3>
                    <span className="font-mono text-xs text-gray-400">#{order.id.slice(0, 6)}</span>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-mono font-medium">{formatTime(order.scheduledTime)}</p>
                  </div>
                </div>

                <div className="border-t border-b border-gray-100 py-4 mb-6 space-y-2">
                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span className="font-medium text-gray-800"><span className="font-mono text-gray-400 mr-2">{item.quantity}x</span> {item.name}</span>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {order.status === OrderStatus.CONFIRMED && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-black bg-white text-noir py-3 text-xs font-bold uppercase tracking-widest hover:bg-black hover:text-white transition-colors"
                    >
                      Start Order
                    </button>
                  )}
                  {order.status === OrderStatus.PREPARING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-black text-white py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-800 transition-colors"
                    >
                      Mark Ready
                    </button>
