                  {order.status === OrderStatus.READY && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-gray-200 text-gray-500 py-3 text-xs font-bold uppercase tracking-widest hover:border-black hover:text-noir transition-colors"
                    >
                      Archive
                    </button>
                  )}

                  {(order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                      className="col-span-2 text-center text-xs text-gray-400 hover:text-red-600 hover:underline mt-1"
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {view === 'menu' && (
        <div className="animate-fade-in space-y-8">
          {!isAddingItem ? (
             <button 
               onClick={() => setIsAddingItem(true)}
               className="flex items-center gap-2 bg-noir text-white px-8 py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-800 transition-colors"
