import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { Loader2, ArrowLeft } from 'lucide-react';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState('');

  if (!user) return <Navigate to={ROUTES.LOGIN} />;
  if (items.length === 0) return <Navigate to={ROUTES.HOME} />;

  const slots = generateTimeSlots();

  const handlePlaceOrder = async () => {
    if (!selectedSlot) return;
    setIsProcessing(true);
    setError('');

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot
      );
      clearCart();
      navigate(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setError("The selected time slot just filled up. Please choose another.");
      } else {
        setError("Something went wrong. Please try again.");
      }
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <button onClick={() => navigate(-1)} className="flex items-center text-xs font-bold uppercase tracking-widest text-gray-500 hover:text-noir mb-8">
        <ArrowLeft className="w-4 h-4 mr-2" /> Return to Menu
      </button>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-16">
        <div>
          <h2 className="text-3xl font-serif font-bold text-noir mb-8">Select Pickup Time</h2>
          <div className="space-y-6">
             <div className="grid grid-cols-3 gap-3">
               {slots.map((slot) => (
                 <button
                   key={slot.toISOString()}
                   onClick={() => setSelectedSlot(slot)}
                   className={`px-2 py-4 text-sm font-mono transition-all border ${
                     selectedSlot === slot
                       ? 'bg-noir text-white border-noir'
                       : 'bg-white border-gray-200 text-gray-500 hover:border-black hover:text-noir'
                   }`}
                 >
                   {formatTime(slot)}
                 </button>
               ))}
             </div>
             {error && <p className="text-red-600 text-sm border border-red-200 bg-red-50 p-4">{error}</p>}
          </div>
        </div>

        <div className="bg-white p-8 border border-black h-fit">
          <h3 className="text-xl font-serif font-bold text-noir mb-6 border-b border-black pb-4">Order Summary</h3>
          <ul className="space-y-4 mb-8">
            {items.map(item => (
              <li key={item.id} className="flex justify-between text-sm">
                <span className="text-noir font-medium"><span className="text-gray-400 mr-2 font-mono">{quantities[item.id]}x</span> {item.name}</span>
                <span className="font-mono text-gray-600">{formatPrice(item.price * quantities[item.id])}</span>
              </li>
            ))}
          </ul>

          <div className="flex justify-between items-center border-t border-dashed border-gray-300 pt-6 mb-8">
            <span className="font-bold text-noir uppercase tracking-widest">Total</span>
            <span className="font-bold font-mono text-2xl">{formatPrice(totalPrice)}</span>
          </div>

          <button
            onClick={handlePlaceOrder}
            disabled={!selectedSlot || isProcessing}
            className="w-full flex justify-center items-center px-6 py-5 bg-noir text-white text-sm font-bold uppercase tracking-widest hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Confirm Order'}
          </button>

          {!selectedSlot && <p className="text-xs text-center text-gray-400 mt-4 uppercase tracking-wide">Please select a pickup time</p>}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { ROUTES, ADMIN_EMAIL } from '../constants';
import { AlertTriangle, Info } from 'lucide-react';

type Tab = 'login' | 'signup' | 'admin';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;
  if (user) return <Navigate to={ROUTES.HOME} />;

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
    if (tab === 'admin') {
      setEmail(ADMIN_EMAIL);
    } else if (email === ADMIN_EMAIL) {
      setEmail('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');
    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        if (!name) throw new Error("Name is required");
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
      }
      navigate(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message || "Action failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      navigate(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-noir mb-2">
            {activeTab === 'signup' ? 'Join Us' : activeTab === 'admin' ? 'Staff Portal' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 font-light">
            {activeTab === 'signup' ? 'Create your account' : activeTab === 'admin' ? 'Restricted access' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-200 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Register
          </button>
          <button
            onClick={() => handleTabChange('admin')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'admin' ? 'text-noir border-b-2 border-noir' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Admin
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-black flex items-start text-left">
              <AlertTriangle className="w-5 h-5 text-noir mr-3 flex-shrink-0" />
              <p className="text-sm font-medium">{displayError}</p>
            </div>
          )}

          {activeTab === 'admin' && (
            <div className="mb-8 p-4 bg-gray-50 border border-gray-200 flex items-start text-left">
              <Info className="w-5 h-5 text-gray-500 mr-3 flex-shrink-0" />
              <div className="text-xs text-gray-600">
                <p>Register as <span className="font-mono font-bold">{ADMIN_EMAIL}</span> in the "Sign Up" tab first if you haven't created the admin account yet.</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 border border-gray-300 focus:border-black outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 border border-gray-300 focus:border-black outline-none transition-colors disabled:bg-gray-50 disabled:text-gray-500"
                required
                readOnly={activeTab === 'admin'}
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 border border-gray-300 focus:border-black outline-none transition-colors"
                required
                minLength={6}
              />
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-noir text-white py-4 font-bold uppercase tracking-widest hover:bg-gray-800 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          {activeTab !== 'admin' && (
            <>
              <div className="relative my-10 text-center">
                <span className="bg-white px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
                <div className="absolute top-1/2 left-0 w-full border-t border-gray-200 -z-10"></div>
              </div>

              <button
                type="button"
                onClick={handleGoogleLogin}
                className="w-full flex items-center justify-center gap-3 border border-black py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-50 transition-all"
              >
                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 grayscale" />
                Continue with Google
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

