            <div className="border-t border-white p-8 space-y-6 bg-black">
              <div className="flex justify-between items-end">
                <p className="text-sm text-gray-500 uppercase tracking-widest">Total</p>
                <p className="font-serif font-bold text-3xl text-white">{formatPrice(totalPrice)}</p>
              </div>
              <button
                onClick={() => {
                  toggleCart();
                  navigate(ROUTES.CHECKOUT);
                }}
                className="w-full flex justify-center items-center px-8 py-4 bg-white text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors"
              >
                Checkout
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [usingMockData, setUsingMockData] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  const isInitialized = useRef(false);

  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              data = await getMenuItems();
            } catch (e) {
              setUsingMockData(true);
              data = MOCK_MENU_ITEMS;
            }
          } else {
             setUsingMockData(true);
             data = MOCK_MENU_ITEMS;
          }
        }

        if (data.length > 0 && data[0].id.startsWith('mock')) {
          setUsingMockData(true);
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]);

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-96 bg-gray-900 border border-gray-800"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-white pb-8">
        <div className="max-w-xl">
          <h1 className="text-5xl font-serif font-bold text-white mb-4 leading-tight">Menu</h1>
          <p className="text-gray-400 font-light text-lg">Curated selection of seasonal dishes focused on simplicity and quality ingredients.</p>
        </div>

        <div className="w-full md:w-auto">
          <div className="flex items-center gap-3 border-b border-gray-700 pb-2 focus-within:border-white transition-colors w-full md:w-64">
            <Search className="w-4 h-4 text-white" />
            <input 
              type="text" 
              placeholder="SEARCH DISHES" 
              className="outline-none text-sm bg-transparent flex-grow placeholder:text-gray-600 font-medium tracking-wide text-white"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Categories */}
      <div className="flex flex-wrap gap-4">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-6 py-2 text-sm font-bold uppercase tracking-widest transition-all border ${
              activeCategory === cat 
                ? 'bg-white text-black border-white' 
                : 'bg-black text-gray-500 border-gray-800 hover:border-white hover:text-white'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
          {filteredItems.map(item => (
            <MenuItemCard key={item.id} item={item} />
          ))}
        </div>
      ) : (
        <div className="text-center py-32 border border-dashed border-gray-800">
            <>
              <p className="text-white font-serif text-2xl italic">No matches found.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); }}
                className="mt-6 text-xs font-bold uppercase tracking-widest border-b border-white pb-1 hover:text-gray-400 hover:border-gray-400"
              >
                Clear all filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { ROUTES, ADMIN_EMAIL } from '../constants';
import { AlertTriangle, Info } from 'lucide-react';

type Tab = 'login' | 'signup' | 'admin';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;
  if (user) return <Navigate to={ROUTES.HOME} />;

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
    if (tab === 'admin') {
      setEmail(ADMIN_EMAIL);
    } else if (email === ADMIN_EMAIL) {
      setEmail('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');
    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        if (!name) throw new Error("Name is required");
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
      }
      navigate(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message || "Action failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      navigate(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-black">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : activeTab === 'admin' ? 'Staff Portal' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 font-light">
            {activeTab === 'signup' ? 'Create your account' : activeTab === 'admin' ? 'Restricted access' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-800 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Register
          </button>
          <button
            onClick={() => handleTabChange('admin')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'admin' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Admin
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-white flex items-start text-left bg-gray-900">
              <AlertTriangle className="w-5 h-5 text-white mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-white">{displayError}</p>
            </div>
          )}

          {activeTab === 'admin' && (
            <div className="mb-8 p-4 bg-gray-900 border border-gray-800 flex items-start text-left">
              <Info className="w-5 h-5 text-gray-400 mr-3 flex-shrink-0" />
              <div className="text-xs text-gray-400">
                <p>Register as <span className="font-mono font-bold text-white">{ADMIN_EMAIL}</span> in the "Sign Up" tab first if you haven't created the admin account yet.</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors disabled:bg-gray-900 disabled:text-gray-600"
                required
                readOnly={activeTab === 'admin'}
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                required
                minLength={6}
              />
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-white text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          {activeTab !== 'admin' && (
            <>
              <div className="relative my-10 text-center">
                <span className="bg-black px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
                <div className="absolute top-1/2 left-0 w-full border-t border-gray-800 -z-10"></div>
              </div>

              <button
                type="button"
                onClick={handleGoogleLogin}
                className="w-full flex items-center justify-center gap-3 border border-white py-4 text-sm font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-all text-white"
              >
                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
                Continue with Google
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
