    spacingUnit: '4px',
    borderRadius: '0px',
  },
  rules: {
    '.Input': {
      borderColor: '#333333',
      backgroundColor: '#000000',
    },
    '.Input:focus': {
      borderColor: '#ffffff',
      boxShadow: 'none',
    }
