  const history = useHistory();

  if (!isCartOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      <div className="absolute inset-0 bg-white/10 backdrop-blur-sm" onClick={toggleCart} />

      <div className="absolute inset-y-0 right-0 max-w-md w-full flex">
        <div className="w-full h-full bg-black border-l border-white flex flex-col animate-slide-in">

          <div className="flex items-center justify-between px-8 py-6 border-b border-white">
            <h2 className="text-2xl font-serif font-bold text-white flex items-center">
              Cart
              <span className="ml-3 text-sm font-mono font-normal text-gray-400">[{items.length}]</span>
            </h2>
            <button onClick={toggleCart} className="text-white hover:rotate-90 transition-transform">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-8 space-y-8">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-6">
