                  <ShoppingBag className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-lg font-serif font-bold text-white">Empty Cart</h3>
                  <p className="text-sm text-gray-500 mt-2 max-w-[200px] mx-auto">Select items from the menu to get started.</p>
                </div>
                <button onClick={toggleCart} className="text-sm font-bold text-white uppercase tracking-widest hover:underline underline-offset-4">
                  View Menu
                </button>
              </div>
            ) : (
              items.map((item) => (
                <div key={item.id} className="flex gap-6 group">
                  <div className="w-20 h-20 flex-shrink-0 bg-gray-900 overflow-hidden border border-gray-800">
                    <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover transition-all" />
                  </div>
                  <div className="flex-1 flex flex-col justify-between py-1">
                    <div className="flex justify-between items-start">
                      <h4 className="font-serif font-bold text-white text-lg leading-none">{item.name}</h4>
                      <p className="text-sm font-mono text-gray-400">{formatPrice(item.price)}</p>
