                          <Minus className="w-3 h-3" />
                        </button>
                        <span className="text-sm font-mono font-medium w-8 text-center border-l border-r border-white/20 py-1 text-white">{quantities[item.id]}</span>
                        <button 
                          onClick={() => updateQuantity(item.id, 1)}
                          className="px-3 py-1 hover:bg-white hover:text-black transition-colors"
                        >
                          <Plus className="w-3 h-3" />
                        </button>
                      </div>
                      <p className="font-mono font-bold text-white">
                        {formatPrice(item.price * quantities[item.id])}
                      </p>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          {items.length > 0 && (
            <div className="border-t border-white p-8 space-y-6 bg-black">
              <div className="flex justify-between items-end">
                <p className="text-sm text-gray-500 uppercase tracking-widest">Total</p>
                <p className="font-serif font-bold text-3xl text-white">{formatPrice(totalPrice)}</p>
              </div>
              <button
                onClick={() => {
                  toggleCart();
                  history.push(ROUTES.CHECKOUT);
                }}
                className="w-full flex justify-center items-center px-8 py-4 bg-white text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors"
              >
                Checkout
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useHistory, Redirect } from 'react-router-dom';
import { ROUTES, ADMIN_EMAIL } from '../constants';
import { AlertTriangle, Info } from 'lucide-react';

type Tab = 'login' | 'signup' | 'admin';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  const history = useHistory();
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;
  if (user) return <Redirect to={ROUTES.HOME} />;

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
    if (tab === 'admin') {
      setEmail(ADMIN_EMAIL);
    } else if (email === ADMIN_EMAIL) {
      setEmail('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');
    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        if (!name) throw new Error("Name is required");
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
      }
      history.push(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message || "Action failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      history.push(ROUTES.HOME);
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-black">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : activeTab === 'admin' ? 'Staff Portal' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 font-light">
            {activeTab === 'signup' ? 'Create your account' : activeTab === 'admin' ? 'Restricted access' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-800 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Register
          </button>
          <button
            onClick={() => handleTabChange('admin')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'admin' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Admin
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-white flex items-start text-left bg-gray-900">
              <AlertTriangle className="w-5 h-5 text-white mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-white">{displayError}</p>
            </div>
          )}

          {activeTab === 'admin' && (
            <div className="mb-8 p-4 bg-gray-900 border border-gray-800 flex items-start text-left">
              <Info className="w-5 h-5 text-gray-400 mr-3 flex-shrink-0" />
              <div className="text-xs text-gray-400">
                <p>Register as <span className="font-mono font-bold text-white">{ADMIN_EMAIL}</span> in the "Sign Up" tab first if you haven't created the admin account yet.</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors disabled:bg-gray-900 disabled:text-gray-600"
                required
                readOnly={activeTab === 'admin'}
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                required
                minLength={6}
              />
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-white text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          {activeTab !== 'admin' && (
            <>
              <div className="relative my-10 text-center">
                <span className="bg-black px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
                <div className="absolute top-1/2 left-0 w-full border-t border-gray-800 -z-10"></div>
              </div>

              <button
                type="button"
                onClick={handleGoogleLogin}
                className="w-full flex items-center justify-center gap-3 border border-white py-4 text-sm font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-all text-white"
              >
                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
                Continue with Google
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useHistory, Redirect } from 'react-router-dom';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { Loader2, ArrowLeft, QrCode } from 'lucide-react';
import { UPIPayment } from '../components/UPIPayment';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const history = useHistory();

  // Checkout State
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [step, setStep] = useState<'slot' | 'payment'>('slot');

  // Loading & Error State
  const [error, setError] = useState('');

  if (!user) return <Redirect to={ROUTES.LOGIN} />;
  if (items.length === 0) return <Redirect to={ROUTES.HOME} />;

  const slots = generateTimeSlots();

  const handleProceedToPayment = () => {
    if (!selectedSlot) return;
    setError('');
    setStep('payment');
  };

  const handlePaymentSuccess = async (transactionId: string) => {
    if (!selectedSlot) return;

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot,
        transactionId
      );
      // Order created successfully
      clearCart();
      history.push(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setError("The selected time slot just filled up. Please select another.");
        setStep('slot');
      } else {
        setError("Failed to create order. Please try again.");
      }
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      {step === 'slot' && (
        <button onClick={() => history.goBack()} className="flex items-center text-xs font-bold uppercase tracking-widest text-gray-500 hover:text-white mb-8">
          <ArrowLeft className="w-4 h-4 mr-2" /> Return to Menu
        </button>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-16 animate-fade-in">

        {/* LEFT COLUMN: Main Interaction Area */}
        <div>
          {step === 'slot' ? (
            <>
              <h2 className="text-3xl font-serif font-bold text-white mb-8">Select Pickup Time</h2>
              <div className="space-y-6">
                 <div className="grid grid-cols-3 gap-3">
                   {slots.map((slot) => (
                     <button
                       key={slot.toISOString()}
                       onClick={() => setSelectedSlot(slot)}
                       className={`px-2 py-4 text-sm font-mono transition-all border ${
                         selectedSlot === slot
                           ? 'bg-white text-black border-white'
                           : 'bg-black border-gray-800 text-gray-500 hover:border-white hover:text-white'
                       }`}
                     >
                       {formatTime(slot)}
                     </button>
                   ))}
                 </div>
                 {error && <p className="text-red-500 text-sm border border-red-900 bg-red-900/20 p-4">{error}</p>}
              </div>
            </>
          ) : (
            <>
              <div className="mb-8">
                 <h2 className="text-3xl font-serif font-bold text-white">Payment</h2>
                 <p className="text-gray-400 mt-2">Scan QR code via UPI to complete order.</p>
              </div>
              <UPIPayment 
                amount={totalPrice} 
                onSuccess={handlePaymentSuccess}
                onCancel={() => setStep('slot')}
              />
            </>
          )}
        </div>

        {/* RIGHT COLUMN: Order Summary */}
        <div className="h-fit">
          <div className="bg-black p-8 border border-white">
            <h3 className="text-xl font-serif font-bold text-white mb-6 border-b border-white pb-4">Order Summary</h3>
            <ul className="space-y-4 mb-8">
              {items.map(item => (
                <li key={item.id} className="flex justify-between text-sm">
                  <span className="text-white font-medium"><span className="text-gray-500 mr-2 font-mono">{quantities[item.id]}x</span> {item.name}</span>
                  <span className="font-mono text-gray-400">{formatPrice(item.price * quantities[item.id])}</span>
                </li>
              ))}
            </ul>

            <div className="flex justify-between items-center border-t border-dashed border-gray-700 pt-6 mb-8">
              <span className="font-bold text-white uppercase tracking-widest">Total</span>
              <span className="font-bold font-mono text-2xl text-white">{formatPrice(totalPrice)}</span>
            </div>

            {step === 'slot' && (
              <button
                onClick={handleProceedToPayment}
                disabled={!selectedSlot}
                className="w-full flex justify-center items-center px-6 py-5 bg-white text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-all group"
              >
                  <>
                    Proceed to Payment <QrCode className="w-4 h-4 ml-2 group-hover:translate-x-1 transition-transform" />
                  </>
              </button>
            )}

            {step === 'slot' && !selectedSlot && (
              <p className="text-xs text-center text-gray-500 mt-4 uppercase tracking-wide">Please select a pickup time</p>
            )}

            {selectedSlot && (
              <div className="mt-6 flex items-center justify-center text-xs text-gray-500 uppercase tracking-widest">
                 Pickup at <span className="text-white font-bold ml-2">{formatTime(selectedSlot)}</span>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { subscribeToAllOrders, updateOrderStatus, getAllMenuItemsAdmin, addMenuItem, updateMenuItem } from '../services/firestoreService';
import { Order, OrderStatus, MenuItem, ProductCategory } from '../types';
import { formatTime, formatPrice } from '../utils/formatters';
import { Redirect } from 'react-router-dom';
import { ROUTES } from '../constants';
import { Utensils, Plus, Image as ImageIcon, X, Coffee, List, Copy, Check } from 'lucide-react';

export const AdminDashboard: React.FC = () => {
  const { user, isAdmin } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);

  const [view, setView] = useState<'kitchen' | 'menu'>('kitchen');
  const [activeOrderTab, setActiveOrderTab] = useState<'active' | 'completed'>('active');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [loadingMenu, setLoadingMenu] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const [newItem, setNewItem] = useState<Partial<MenuItem>>({
    name: '',
    description: '',
    price: 0,
    category: ProductCategory.Lunch,
    imageUrl: '',
    preparationTime: 10,
    isAvailable: true
  });

  useEffect(() => {
    if (!isAdmin) return;
    const unsubscribe = subscribeToAllOrders((data) => {
      setOrders(data);
    });
    return () => unsubscribe();
  }, [isAdmin]);

  useEffect(() => {
    if (view === 'menu' && isAdmin) {
      setLoadingMenu(true);
      getAllMenuItemsAdmin()
        .then(setMenuItems)
        .finally(() => setLoadingMenu(false));
    }
  }, [view, isAdmin, isAddingItem]);

  if (!user || !isAdmin) return <Redirect to={ROUTES.HOME} />;

  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const handleToggleAvailability = async (id: string, currentStatus: boolean) => {
    try {
      await updateMenuItem(id, { isAvailable: !currentStatus });
      setMenuItems(prev => prev.map(item => item.id === id ? { ...item, isAvailable: !currentStatus } : item));
    } catch (e) {
      console.error("Failed to toggle availability", e);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addMenuItem(newItem as MenuItem);
      setIsAddingItem(false);
      setNewItem({
        name: '',
        description: '',
        price: 0,
        category: ProductCategory.Lunch,
        imageUrl: '',
        preparationTime: 10,
        isAvailable: true
      });
    } catch (e) {
      console.error("Failed to add item", e);
      alert("Failed to add item. Check permissions.");
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(text);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const activeOrders = orders.filter(o => [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));
  const displayOrders = activeOrderTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-12 pb-20">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 border-b border-white pb-8">
        <div>
           <h1 className="text-4xl font-serif font-bold text-white animate-fade-in">Command Center</h1>
        </div>

        <div className="flex border border-white p-1">
          <button
            onClick={() => setView('kitchen')}
            className={`flex items-center px-6 py-2 text-xs font-bold uppercase tracking-widest transition-all duration-300 ${view === 'kitchen' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
          >
            Kitchen
          </button>
          <button
            onClick={() => setView('menu')}
            className={`flex items-center px-6 py-2 text-xs font-bold uppercase tracking-widest transition-all duration-300 ${view === 'menu' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
          >
            Menu
          </button>
        </div>
      </div>

      {view === 'kitchen' && (
        <div className="space-y-8 animate-fade-in">
          <div className="flex gap-8 border-b border-gray-800">
             <button 
               onClick={() => setActiveOrderTab('active')}
               className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'active' ? 'border-b-2 border-white text-white' : 'border-transparent text-gray-500 hover:text-white'}`}
             >
               Live Orders ({activeOrders.length})
             </button>
             <button 
               onClick={() => setActiveOrderTab('completed')}
               className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'completed' ? 'border-b-2 border-white text-white' : 'border-transparent text-gray-500 hover:text-white'}`}
             >
               Archive
             </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {displayOrders.length === 0 && (
              <div className="col-span-full text-center py-24 border border-dashed border-gray-800 animate-fade-in">
                <Coffee className="w-8 h-8 text-gray-600 mx-auto mb-4" />
                <p className="text-gray-500 font-mono text-sm">No orders in queue.</p>
              </div>
            )}

            {displayOrders.map(order => (
              <div key={order.id} className={`bg-black border p-6 transition-all duration-500 animate-fade-in relative ${order.status === OrderStatus.READY ? 'border-white ring-1 ring-white' : 'border-gray-800'}`}>
                {order.status === OrderStatus.READY && (
                    <div className="absolute top-0 left-0 right-0 bg-white text-black text-xs font-bold text-center py-1 uppercase tracking-widest animate-pop">Ready for Pickup</div>
                )}

                <div className={`flex justify-between items-start mb-4 ${order.status === OrderStatus.READY ? 'mt-4' : ''}`}>
                  <div>
                    <h3 className="font-bold text-xl text-white">{order.userEmail.split('@')[0]}</h3>
                    <span className="font-mono text-xs text-gray-500">#{order.id.slice(0, 6)}</span>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-mono font-medium text-white">{formatTime(order.scheduledTime)}</p>
                    <p className="text-xs text-gray-400 font-mono mt-1">{formatPrice(order.totalAmount)}</p>
                  </div>
                </div>

                {/* Transaction ID Display */}
                <div className="bg-gray-900 border border-gray-800 p-2 mb-4 flex items-center justify-between">
                  <div>
                    <span className="block text-[10px] text-gray-500 uppercase tracking-wider">Transaction ID</span>
                    <span className="text-xs font-mono text-white">{order.transactionId || 'N/A'}</span>
                  </div>
                  {order.transactionId && (
                    <button 
                      onClick={() => copyToClipboard(order.transactionId)}
                      className="text-gray-400 hover:text-white p-1"
                      title="Copy ID"
                    >
                      {copiedId === order.transactionId ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                    </button>
                  )}
                </div>

                <div className="border-t border-b border-gray-800 py-4 mb-6 space-y-2">
                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span className="font-medium text-gray-300"><span className="font-mono text-gray-500 mr-2">{item.quantity}x</span> {item.name}</span>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {order.status === OrderStatus.PENDING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CONFIRMED)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-white text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors duration-200"
                    >
                      Verify & Accept
                    </button>
                  )}
                  {order.status === OrderStatus.CONFIRMED && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-white bg-black text-white py-3 text-xs font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-colors duration-200"
                    >
                      Start Preparation
                    </button>
                  )}
                  {order.status === OrderStatus.PREPARING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-white text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors duration-200"
                    >
                      Mark Ready
                    </button>
                  )}
                  {order.status === OrderStatus.READY && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-gray-700 text-gray-400 py-3 text-xs font-bold uppercase tracking-widest hover:border-white hover:text-white transition-colors duration-200"
                    >
                      Archive
                    </button>
                  )}

                  {(order.status === OrderStatus.PENDING || order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                      className="col-span-2 text-center text-xs text-gray-500 hover:text-red-500 hover:underline mt-1 transition-colors duration-200"
                    >
                      Reject / Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {view === 'menu' && (
        <div className="animate-fade-in space-y-8">
          {!isAddingItem ? (
             <button 
               onClick={() => setIsAddingItem(true)}
               className="flex items-center gap-2 bg-white text-black px-8 py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors"
             >
               <Plus className="w-4 h-4" /> Add Item
             </button>
          ) : (
            <div className="bg-black border border-white p-8 max-w-2xl animate-fade-in">
              <div className="flex justify-between items-center mb-8 border-b border-white pb-4">
                <h2 className="text-2xl font-serif font-bold text-white">New Item</h2>
                <button onClick={() => setIsAddingItem(false)} className="text-gray-400 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
              </div>

              <form onSubmit={handleAddItem} className="space-y-6">
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Name</label>
                    <input 
                      required
                      type="text" 
                      value={newItem.name}
                      onChange={e => setNewItem({...newItem, name: e.target.value})}
                      className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none transition-colors"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Price</label>
                    <input 
                      required
                      type="number" 
                      step="0.01"
                      value={newItem.price}
                      onChange={e => setNewItem({...newItem, price: parseFloat(e.target.value)})}
                      className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none transition-colors"
                    />
                  </div>
                </div>

                <div>
                   <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Description</label>
                   <textarea 
                      required
                      value={newItem.description}
                      onChange={e => setNewItem({...newItem, description: e.target.value})}
                      className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none h-24 resize-none"
                    />
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Category</label>
                    <select 
                      value={newItem.category}
                      onChange={e => setNewItem({...newItem, category: e.target.value as ProductCategory})}
                      className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none"
                    >
                      {Object.values(ProductCategory).map(c => (
                        <option key={c} value={c} className="capitalize bg-black">{c}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Prep (min)</label>
                    <input 
                      required
                      type="number" 
                      value={newItem.preparationTime}
                      onChange={e => setNewItem({...newItem, preparationTime: parseInt(e.target.value)})}
                      className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Image URL</label>
                  <input 
                    required
                    type="url" 
                    placeholder="https://..."
                    value={newItem.imageUrl}
                    onChange={e => setNewItem({...newItem, imageUrl: e.target.value})}
                    className="w-full bg-black border border-gray-700 px-4 py-3 focus:border-white text-white outline-none"
                  />
                </div>

                <div className="pt-6 flex justify-end gap-4">
                  <button type="button" onClick={() => setIsAddingItem(false)} className="px-6 py-3 text-sm font-bold uppercase tracking-widest text-gray-400 hover:text-white transition-colors">Cancel</button>
                  <button type="submit" className="px-8 py-3 bg-white text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors">Save</button>
                </div>
              </form>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
             {menuItems.map(item => (
               <div key={item.id} className={`flex gap-6 p-4 border transition-all duration-300 animate-fade-in ${!item.isAvailable ? 'opacity-50 border-dashed border-gray-700 bg-gray-900' : 'border-gray-800 bg-black'}`}>
                 <div className="w-24 h-24 bg-gray-900 flex-shrink-0">
                   <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                 </div>

                 <div className="flex-grow flex flex-col justify-between py-1">
                   <div>
                     <div className="flex justify-between items-start">
                       <h3 className="font-bold text-white text-lg">{item.name}</h3>
                       <span className="font-mono text-sm text-gray-400">{formatPrice(item.price)}</span>
                     </div>
                     <p className="text-sm text-gray-500 line-clamp-1 mt-1">{item.description}</p>
                   </div>

                   <div className="flex items-center justify-between mt-2">
                      <button 
                        onClick={() => handleToggleAvailability(item.id, item.isAvailable)}
                        className={`text-xs font-bold uppercase tracking-widest underline underline-offset-4 transition-colors duration-200 ${item.isAvailable ? 'text-white' : 'text-gray-500'}`}
                      >
                        {item.isAvailable ? 'Active' : 'Sold Out'}
                      </button>
                   </div>
                 </div>
               </div>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { HashRouter as Router, Switch, Route } from 'react-router-dom';
import { AuthProvider } from './contexts/AuthContext';
import { CartProvider } from './contexts/CartContext';
import { Layout } from './components/Layout';
import { Home } from './pages/Home';
import { Login } from './pages/Login';
import { Orders } from './pages/Orders';
import { AdminDashboard } from './pages/AdminDashboard';
import { Checkout } from './pages/Checkout';
import { FirebaseSetup } from './components/FirebaseSetup';
import { isFirebaseConfigured } from './firebase';
import { ROUTES } from './constants';

const App: React.FC = () => {
  if (!isFirebaseConfigured) {
    return <FirebaseSetup />;
  }

  return (
    <AuthProvider>
      <CartProvider>
        <Router>
          <Layout>
            <Switch>
              <Route exact path={ROUTES.HOME} component={Home} />
              <Route path={ROUTES.LOGIN} component={Login} />
              <Route path={ROUTES.ORDERS} component={Orders} />
              <Route path={ROUTES.ADMIN} component={AdminDashboard} />
              <Route path={ROUTES.CHECKOUT} component={Checkout} />
            </Switch>
          </Layout>
        </Router>
      </CartProvider>
    </AuthProvider>
  );
};

export default App;

