import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from '../contexts/AuthContext';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { ArrowLeft, QrCode } from 'lucide-react';
import { UPIPayment } from '../components/UPIPayment';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  // Checkout State
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [step, setStep] = useState<'slot' | 'payment'>('slot');

  // Loading & Error State
  const [error, setError] = useState('');

  if (!user) return <Navigate to={ROUTES.LOGIN} replace />;
  if (items.length === 0) return <Navigate to={ROUTES.HOME} replace />;

  const slots = generateTimeSlots();

  const handleProceedToPayment = () => {
    if (!selectedSlot) return;
    setError('');
    setStep('payment');
  };

  const handlePaymentSuccess = async (transactionId: string) => {
    if (!selectedSlot) return;

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot,
        transactionId
      );
      // Order created successfully
      clearCart();
      navigate(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setError("The selected time slot just filled up. Please select another.");
        setStep('slot');
      } else {
        setError("Failed to create order. Please try again.");
      }
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      {step === 'slot' && (
        <button onClick={() => navigate(-1)} className="flex items-center text-xs font-bold uppercase tracking-widest text-gray-500 hover:text-white mb-8">
          <ArrowLeft className="w-4 h-4 mr-2" /> Return to Menu
        </button>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-16 animate-fade-in">

        {/* LEFT COLUMN: Main Interaction Area */}
        <div>
          {step === 'slot' ? (
            <>
              <h2 className="text-3xl font-serif font-bold text-white mb-8">Select Pickup Time</h2>
              <div className="space-y-6">
                 <div className="grid grid-cols-3 gap-3">
                   {slots.map((slot) => (
                     <button
                       key={slot.toISOString()}
                       onClick={() => setSelectedSlot(slot)}
                       className={`px-2 py-4 text-sm font-mono transition-all border ${
                         selectedSlot === slot
                           ? 'bg-white text-black border-white'
                           : 'bg-black border-gray-800 text-gray-500 hover:border-white hover:text-white'
                       }`}
                     >
                       {formatTime(slot)}
                     </button>
                   ))}
                 </div>
                 {error && <p className="text-red-500 text-sm border border-red-900 bg-red-900/20 p-4">{error}</p>}
              </div>
            </>
          ) : (
            <>
              <div className="mb-8">
                 <h2 className="text-3xl font-serif font-bold text-white">Payment</h2>
                 <p className="text-gray-400 mt-2">Scan QR code via UPI to complete order.</p>
              </div>
              <UPIPayment 
                amount={totalPrice} 
                onSuccess={handlePaymentSuccess}
                onCancel={() => setStep('slot')}
              />
            </>
          )}
        </div>

        {/* RIGHT COLUMN: Order Summary */}
        <div className="h-fit">
          <div className="bg-black p-8 border border-white">
            <h3 className="text-xl font-serif font-bold text-white mb-6 border-b border-white pb-4">Order Summary</h3>
            <ul className="space-y-4 mb-8">
              {items.map(item => (
                <li key={item.id} className="flex justify-between text-sm">
                  <span className="text-white font-medium"><span className="text-gray-500 mr-2 font-mono">{quantities[item.id]}x</span> {item.name}</span>
                  <span className="font-mono text-gray-400">{formatPrice(item.price * quantities[item.id])}</span>
                </li>
              ))}
            </ul>

            <div className="flex justify-between items-center border-t border-dashed border-gray-700 pt-6 mb-8">
              <span className="font-bold text-white uppercase tracking-widest">Total</span>
              <span className="font-bold font-mono text-2xl text-white">{formatPrice(totalPrice)}</span>
            </div>

            {step === 'slot' && (
              <button
                onClick={handleProceedToPayment}
                disabled={!selectedSlot}
                className="w-full flex justify-center items-center px-6 py-5 bg-white text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-all group"
              >
                  <>
                    Proceed to Payment <QrCode className="w-4 h-4 ml-2 group-hover:translate-x-1 transition-transform" />
                  </>
              </button>
            )}

            {step === 'slot' && !selectedSlot && (
              <p className="text-xs text-center text-gray-500 mt-4 uppercase tracking-wide">Please select a pickup time</p>
            )}

            {selectedSlot && (
              <div className="mt-6 flex items-center justify-center text-xs text-gray-500 uppercase tracking-widest">
                 Pickup at <span className="text-white font-bold ml-2">{formatTime(selectedSlot)}</span>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { UPI_VPA, UPI_PAYEE_NAME } from '../constants';
import { formatPrice } from '../utils/formatters';
import { Loader2, Send } from 'lucide-react';

interface UPIPaymentProps {
  amount: number;
  onSuccess: (transactionId: string) => Promise<void>;
  onCancel: () => void;
}

export const UPIPayment: React.FC<UPIPaymentProps> = ({ amount, onSuccess, onCancel }) => {
  const [transactionId, setTransactionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  // Construct UPI URL
  // format: upi://pay?pa=<vpa>&pn=<name>&am=<amount>&cu=<currency>
  const upiUrl = `upi://pay?pa=${UPI_VPA}&pn=${encodeURIComponent(UPI_PAYEE_NAME)}&am=${amount.toFixed(2)}&cu=INR`;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transactionId.trim()) {
      setError("Please enter the Transaction ID / UTR");
      return;
    }

    setError('');
    setIsSubmitting(true);
    try {
      await onSuccess(transactionId);
    } catch (err) {
      setError("Failed to process order. Please try again.");
      setIsSubmitting(false);
    }
  };

  return (
    <div className="animate-fade-in space-y-8">

      <div className="bg-white text-black p-6 border border-gray-200">
        <h3 className="font-serif font-bold text-xl mb-6 text-center">Scan to Pay</h3>

        <div className="flex flex-col items-center justify-center space-y-4">
          <div className="bg-white p-4 border-2 border-dashed border-gray-300">
             <QRCodeSVG value={upiUrl} size={200} />
          </div>

          <div className="text-center">
            <p className="text-3xl font-mono font-bold">{formatPrice(amount)}</p>
            <p className="text-xs text-gray-500 uppercase tracking-widest mt-1">to {UPI_PAYEE_NAME}</p>
          </div>
        </div>

        <div className="mt-6 pt-6 border-t border-gray-200">
          <p className="text-xs text-center text-gray-500 leading-relaxed">
             Open PhonePe, Google Pay, or Paytm.<br/>
             Scan QR code and complete payment.<br/>
             <strong className="text-black">Copy the UTR / Transaction ID.</strong>
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-black border border-white p-6">
        <h4 className="text-white font-serif font-bold mb-4">Verification</h4>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Transaction ID / UTR</label>
            <input 
              type="text" 
              value={transactionId}
              onChange={(e) => setTransactionId(e.target.value)}
              placeholder="e.g. 308572189..."
              className="w-full bg-gray-900 border border-gray-700 px-4 py-3 focus:border-white text-white outline-none transition-colors font-mono"
            />
            {error && <p className="text-red-500 text-xs mt-2">{error}</p>}
          </div>

          <div className="flex gap-4 pt-2">
            <button
              type="button"
              onClick={onCancel}
              disabled={isSubmitting}
              className="flex-1 py-4 text-sm font-bold uppercase tracking-widest text-gray-500 hover:text-white transition-colors border border-transparent hover:border-gray-800"
            >
              Back
            </button>
            <button
              type="submit"
              disabled={!transactionId || isSubmitting}
              className="flex-1 bg-white text-black py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 flex justify-center items-center"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <>Submit Order <Send className="w-4 h-4 ml-2" /></>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { PaymentElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { Loader2, Lock } from 'lucide-react';
import { formatPrice } from '../utils/formatters';

interface PaymentFormProps {
  amount: number;
  onSuccess: (paymentId: string) => Promise<void>;
  onCancel: () => void;
}

export const PaymentForm: React.FC<PaymentFormProps> = ({ amount, onSuccess, onCancel }) => {
  const stripe = useStripe();
  const elements = useElements();
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    if (!stripe || !elements) return;

    setIsProcessing(true);
    setErrorMessage(null);

    // 1. Confirm Payment with Stripe
    const { error, paymentIntent } = await stripe.confirmPayment({
      elements,
      redirect: 'if_required', // Prevents redirecting if not using 3D secure
    });

    if (error) {
      setErrorMessage(error.message ?? "Payment failed");
      setIsProcessing(false);
    } else if (paymentIntent && paymentIntent.status === 'succeeded') {
      // 2. Payment Succeeded, trigger parent callback to save order
      try {
        await onSuccess(paymentIntent.id);
      } catch (e) {
        setErrorMessage("Payment succeeded but order creation failed. Please contact support.");
        setIsProcessing(false);
      }
    } else {
      setErrorMessage("Unexpected payment status.");
      setIsProcessing(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="animate-fade-in">
      <div className="bg-black border border-white p-6 mb-6">
        <div className="flex items-center justify-between mb-6 border-b border-gray-800 pb-4">
          <h3 className="text-xl font-serif font-bold text-white">Secure Payment</h3>
          <Lock className="w-4 h-4 text-gray-500" />
        </div>

        <PaymentElement />

        {errorMessage && (
          <div className="mt-4 p-3 bg-red-900/20 border border-red-900 text-red-200 text-sm">
            {errorMessage}
          </div>
        )}
      </div>

      <div className="flex gap-4">
        <button
          type="button"
          onClick={onCancel}
          disabled={isProcessing}
          className="flex-1 py-4 text-sm font-bold uppercase tracking-widest text-gray-500 hover:text-white transition-colors border border-transparent hover:border-gray-800"
        >
          Back
        </button>
        <button
          type="submit"
          disabled={!stripe || isProcessing}
          className="flex-1 bg-white text-black py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 flex justify-center items-center"
        >
          {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : `Pay ${formatPrice(amount)}`}
        </button>
      </div>
    </form>
  );
};

